  var section by remember{mutableStateOf("HOME")};var category by remember{mutableStateOf<Category?>(null)};var query by remember{mutableStateOf("")};var loading by remember{mutableStateOf(false)};var status by remember{mutableStateOf("")};var error by remember{mutableStateOf("")};var settings by remember{mutableStateOf(url.isBlank())};var current by remember{mutableStateOf<IptvItem?>(null)}
  var seriesTitle by remember{mutableStateOf<String?>(null)};var previousSeriesList by remember{mutableStateOf<List<IptvItem>>(emptyList())};var epgNow by remember{mutableStateOf<Map<String,String>>(emptyMap())};var favorites by remember{mutableStateOf(readFavorites(prefs.getString("favorites","[]")?:"[]"))};var searchCatalog by remember{mutableStateOf<List<IptvItem>>(emptyList())};var searchLoading by remember{mutableStateOf(false)};var hiddenGroups by remember{mutableStateOf(prefs.getStringSet("hidden_groups",emptySet())?.toSet()?:emptySet())};var groupOrder by remember{mutableStateOf(readStringList(prefs.getString("group_order","[]")?:"[]"))};var expiry by remember{mutableStateOf("Non disponibile")};var initializing by remember{mutableStateOf(false)};var preloadDone by remember{mutableIntStateOf(0)};var preloadTotal by remember{mutableIntStateOf(1)};var preloadLabel by remember{mutableStateOf("Preparazione…")}
