  fun loadRemote(target:String,cat:Category){val config=xtream?:return;val apiTarget=if(target=="GUIDA TV")"LIVE"else target;section=target;category=cat;query="";seriesTitle=null;loading=true;status="Caricamento ${cat.name}…";error="";scope.launch{try{val loaded=withContext(Dispatchers.IO){loadXtreamCategory(config,apiTarget,cat)};catalog=loaded}catch(e:Exception){error=e.message?:"Categoria non disponibile";catalog=emptyList()}finally{loading=false;status=""}}}
  fun selectCategory(target:String,cat:Category){val kind=if(target=="GUIDA TV")"LIVE"else target;val ready=searchCatalog.filter{it.kind==kind&&it.group==cat.name};if(ready.isNotEmpty()){section=target;category=cat;catalog=ready;query="";seriesTitle=null}else loadRemote(target,cat)}
  fun switchSection(target:String){section=target;seriesTitle=null;if(target=="HOME"){category=null;query="";return};if(target=="CERCA"){category=null;query="";if(searchCatalog.isEmpty()&&xtream!=null&&!searchLoading){searchLoading=true;scope.launch{try{searchCatalog=withContext(Dispatchers.IO){loadFullCatalog(xtream!!,categoryMap)}}catch(e:Exception){error=e.message?:"Ricerca non disponibile"}finally{searchLoading=false}}};return};if(target=="PREFERITI"){catalog=favorites;category=null;query="";return};val mapKey=if(target=="GUIDA TV")"LIVE"else target;val first=categoryMap[mapKey]?.firstOrNull{!hiddenGroups.contains("$mapKey:${it.id}")};if(xtream!=null&&first!=null)selectCategory(target,first)else{category=null;query=""}}
  fun toggleFavorite(item:IptvItem){favorites=if(favorites.any{it.id==item.id})favorites.filterNot{it.id==item.id}else favorites+item;prefs.edit().putString("favorites",writeFavorites(favorites)).apply();if(section=="PREFERITI")catalog=favorites}
  fun moveGroup(key:String,step:Int){val kind=key.substringBefore(":");val sectionKeys=categoryMap[kind].orEmpty().map{"$kind:${it.id}"};val sectionOrder=(groupOrder.filter{it in sectionKeys}+sectionKeys).distinct().toMutableList();val index=sectionOrder.indexOf(key);val target=(index+step).coerceIn(0,sectionOrder.lastIndex);if(index>=0&&index!=target){val value=sectionOrder.removeAt(index);sectionOrder.add(target,value);val other=groupOrder.filterNot{it in sectionKeys};val allKnown=categoryMap.flatMap{(section,cats)->cats.map{"$section:${it.id}"}};groupOrder=(other+sectionOrder+allKnown).distinct();prefs.edit().putString("group_order",writeStringList(groupOrder)).apply()}}
  fun connect(address:String=url,sourceName:String=name){if(address.isBlank()){error="Inserisci il link della playlist";return};url=address;name=sourceName;loading=true;status="Aggiornamento playlist…";error="";scope.launch{try{val data=withContext(Dispatchers.IO){importSource(address)};val isNewProfile=profiles.none{it.url==address};val setupCategories=if(data.categories.isNotEmpty())data.categories else data.items.groupBy{it.kind}.mapValues{entry->entry.value.map{it.group}.distinct().map{Category(it,it)}};if(isNewProfile&&setupCategories.isNotEmpty()){xtream=data.xtream;categoryMap=setupCategories;catalog=data.items;val created=PlaylistProfile(sourceName,address);profiles=profiles+created;prefs.edit().putString("playlist_url",address).putString("source_name",sourceName).putString("profiles",writeProfiles(profiles)).apply();hiddenGroups=setupCategories.flatMap{(kind,cats)->cats.map{"$kind:${it.id}"}}.toSet();prefs.edit().putStringSet("hidden_groups",hiddenGroups).apply();pendingProfile=created;setupSelection=true;profileSelection=false;settings=false;return@launch};xtream=data.xtream;categoryMap=data.categories;catalog=data.items;val updated=(profiles.filterNot{it.url==address}+PlaylistProfile(sourceName,address));profiles=updated;prefs.edit().putString("playlist_url",address).putString("source_name",sourceName).putString("profiles",writeProfiles(updated)).apply();settings=false;profileSelection=false;if(data.xtream!=null){expiry=withContext(Dispatchers.IO){subscriptionExpiry(data.xtream)};val first=data.categories["LIVE"]?.firstOrNull();if(first!=null){category=first;status="Preparazione Home…";val prepared=withContext(Dispatchers.IO){prepareHome(data.xtream,data.categories)};homeLive=prepared.first;homeMovies=prepared.second;catalog=homeLive.ifEmpty{loadXtreamCategory(data.xtream,"LIVE",first)};section="HOME"}}else{expiry="Non fornita per collegamenti M3U";homeLive=data.items.filter{it.kind=="LIVE"};homeMovies=data.items.filter{it.kind=="FILM"&&!isAdult(it.group)};section="HOME"}}catch(e:Exception){error=e.message?:"Importazione non riuscita"}finally{loading=false;status=""}}}
  fun preloadProfile(profile:PlaylistProfile,force:Boolean=false){
    url=profile.url;name=profile.name;profileSelection=false;setupSelection=false;initializing=true;preloadDone=0;preloadTotal=1;preloadLabel="Preparazione del profilo…";error=""
    scope.launch{try{
      val cached=if(force)null else withContext(Dispatchers.IO){readCatalogCache(context,profile.url)}
      if(cached!=null){
        preloadLabel="Apertura catalogo e Guida TV salvati…";categoryMap=cached.categories;searchCatalog=cached.items;epgNow=withContext(Dispatchers.IO){readEpgCache(context,profile.url)}?:cached.epg;xtream=parseXtream(profile.url);val selectedGroups=categoryMap["LIVE"].orEmpty().filterNot{hiddenGroups.contains("LIVE:${it.id}")}.map{it.name}.toSet();val selectedLive=searchCatalog.filter{it.kind=="LIVE"&&it.group in selectedGroups};preloadTotal=(selectedGroups.size+1).coerceAtLeast(1);preloadDone=1;val config=xtream;if(config!=null&&selectedLive.isNotEmpty()){val fresh=withContext(Dispatchers.IO){loadBestCurrentPrograms(config,selectedLive){group,done,_->scope.launch{preloadLabel="Caricamento EPG • $group";preloadDone=(done+1).coerceAtMost(preloadTotal)}}};if(fresh.isNotEmpty()){epgNow=epgNow+fresh;withContext(Dispatchers.IO){saveEpgCache(context,profile.url,epgNow)}}};preloadDone=preloadTotal
      }else{
        preloadLabel="Connessione alla playlist…";val data=withContext(Dispatchers.IO){importSource(profile.url)};xtream=data.xtream
        val effectiveCategories=if(data.categories.isNotEmpty())data.categories else categoryMap;categoryMap=effectiveCategories;prefs.edit().putString("playlist_url",profile.url).putString("source_name",profile.name).apply();val config=data.xtream
        if(config==null){preloadTotal=2;preloadLabel="Indicizzazione titoli…";val hiddenNames=effectiveCategories.flatMap{(kind,cats)->cats.filter{hiddenGroups.contains("$kind:${it.id}")}.map{it.name}}.toSet();searchCatalog=data.items.filterNot{hiddenNames.contains(it.group)};epgNow=emptyMap();preloadDone=2}else{
          val jobs=listOf("LIVE","FILM","SERIE").flatMap{kind->effectiveCategories[kind].orEmpty().filterNot{hiddenGroups.contains("$kind:${it.id}")}.sortedBy{val p=groupOrder.indexOf("$kind:${it.id}");if(p<0)Int.MAX_VALUE else p}.map{kind to it}}
