@Composable fun PairingPanel(modifier:Modifier,onSaved:(String,String)->Unit){val activity=LocalContext.current as ComponentActivity;val ip=remember{localIpv4()};val pin=remember{(100000..999999).random().toString()};val address=if(ip==null)""else"http://$ip:8766/?pin=$pin";val server=remember(ip,pin){if(ip==null)null else PairingServer(8766,pin){name,url->activity.runOnUiThread{onSaved(name,url)}}};DisposableEffect(server){try{server?.start(3000,false)}catch(_:Exception){};onDispose{server?.stop()}};Column(modifier.background(Color(0xEE111A2A),RoundedCornerShape(20.dp)).padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("AGGIUNGI DAL TELEFONO",fontWeight=FontWeight.Black,color=Color(0xFF3EE7E1));Spacer(Modifier.height(8.dp));Text("Scansiona il QR con il telefono collegato allo stesso Wi-Fi.",fontSize=12.sp,color=Color(0xFF9BA7BC));Spacer(Modifier.height(16.dp));if(address.isNotBlank()){val qr=remember(address){qrBitmap(address,270)};Image(qr.asImageBitmap(),"QR per configurare la playlist",Modifier.size(270.dp));Spacer(Modifier.height(9.dp));Text("Codice $pin",fontWeight=FontWeight.Bold)}else Text("Connessione Wi-Fi non rilevata",color=Color(0xFFFF8295))}}

class PairingServer(port:Int,private val pin:String,private val saved:(String,String)->Unit):NanoHTTPD(port){override fun serve(session:IHTTPSession):Response{return try{if(session.parameters["pin"]?.firstOrNull()!=pin)return newFixedLengthResponse(Response.Status.FORBIDDEN,"text/plain","Codice non valido");if(session.method==Method.POST){session.parseBody(HashMap());val p=session.parameters;val name=p["name"]?.firstOrNull()?.trim().orEmpty().ifBlank{"Playlist telefono"};val mode=p["mode"]?.firstOrNull();val address=if(mode=="xtream"){val server=p["server"]?.firstOrNull()?.trim()?.trimEnd('/').orEmpty();val user=URLEncoder.encode(p["username"]?.firstOrNull().orEmpty(),"UTF-8");val pass=URLEncoder.encode(p["password"]?.firstOrNull().orEmpty(),"UTF-8");if(server.isBlank()||user.isBlank()||pass.isBlank())return newFixedLengthResponse(Response.Status.BAD_REQUEST,"text/html","Dati Xtream incompleti");"$server/get.php?username=$user&password=$pass&type=m3u_plus&output=ts"}else p["m3u"]?.firstOrNull()?.trim().orEmpty();if(address.isBlank())return newFixedLengthResponse(Response.Status.BAD_REQUEST,"text/html","Inserisci il collegamento");saved(name,address);return newFixedLengthResponse(Response.Status.OK,"text/html; charset=utf-8","<meta name='viewport' content='width=device-width'><body style='font-family:sans-serif;background:#07101b;color:white;padding:30px'><h1>Playlist salvata</h1><p>Puoi tornare su LM IPTV.</p></body>")};newFixedLengthResponse(Response.Status.OK,"text/html; charset=utf-8",pairingHtml(pin))}catch(e:Exception){newFixedLengthResponse(Response.Status.INTERNAL_ERROR,"text/plain","Errore: ${e.message}")}}}

fun pairingHtml(pin:String)="""<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font-family:system-ui;background:#07101b;color:#fff;margin:0;padding:22px}main{max-width:580px;margin:auto}h1{color:#3ee7e1}section{background:#111b2c;padding:20px;border-radius:16px;margin:16px 0}input,select,button{box-sizing:border-box;width:100%;padding:14px;margin:7px 0;border-radius:10px;border:1px solid #34425b;background:#07101b;color:#fff}button{background:#3ee7e1;color:#06101a;font-weight:800;border:0}</style></head><body><main><h1>LM IPTV</h1><p>Configura la playlist sulla Fire TV.</p><form method="post" action="/?pin=$pin"><input name="name" placeholder="Nome playlist" required><select name="mode" onchange="document.getElementById('m3u').hidden=this.value!='m3u';document.getElementById('xt').hidden=this.value!='xtream'"><option value="m3u">Link M3U</option><option value="xtream">Xtream Codes</option></select><section id="m3u"><input name="m3u" placeholder="Link M3U / M3U8"></section><section id="xt" hidden><input name="server" placeholder="URL server"><input name="username" placeholder="Username"><input name="password" type="password" placeholder="Password"></section><button type="submit">SALVA SULLA FIRE TV</button></form></main></body></html>"""
fun localIpv4():String?{return try{Collections.list(NetworkInterface.getNetworkInterfaces()).flatMap{Collections.list(it.inetAddresses)}.firstOrNull{!it.isLoopbackAddress&&it.hostAddress?.contains(':')==false}?.hostAddress}catch(_:Exception){null}}
fun deviceMacAddress():String{return try{val interfaces=Collections.list(NetworkInterface.getNetworkInterfaces());val network=interfaces.firstOrNull{it.name.equals("wlan0",true)&&it.hardwareAddress!=null}?:interfaces.firstOrNull{!it.isLoopback&&it.hardwareAddress!=null};network?.hardwareAddress?.joinToString(":"){byte->"%02X".format(byte.toInt() and 0xFF)}?:"NON DISPONIBILE"}catch(_:Exception){"NON DISPONIBILE"}}
fun qrBitmap(text:String,size:Int):Bitmap{val matrix=QRCodeWriter().encode(text,BarcodeFormat.QR_CODE,size,size);return Bitmap.createBitmap(size,size,Bitmap.Config.RGB_565).also{bitmap->for(y in 0 until size)for(x in 0 until size)bitmap.setPixel(x,y,if(matrix[x,y])android.graphics.Color.BLACK else android.graphics.Color.WHITE)}}
