  Box(Modifier.fillMaxSize().background(Color.Black)){
    AndroidView(factory={PlayerView(it).apply{keepScreenOn=true;player=exo;useController=true;controllerAutoShow=false;controllerHideOnTouch=true;controllerShowTimeoutMs=3000;setControllerVisibilityListener(PlayerView.ControllerVisibilityListener{visibility->controlsVisible=visibility==View.VISIBLE});setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);findViewById<DefaultTimeBar?>(androidx.media3.ui.R.id.exo_progress)?.apply{setPlayedColor(android.graphics.Color.rgb(229,9,20));setScrubberColor(android.graphics.Color.WHITE);setBufferedColor(android.graphics.Color.DKGRAY);setUnplayedColor(android.graphics.Color.GRAY)};layoutParams=FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.MATCH_PARENT)}},modifier=Modifier.fillMaxSize())
    if(item.kind!="LIVE"&&controlsVisible)Text(formatPlaybackTime(playbackPosition),color=Color.White,fontSize=13.sp,fontWeight=FontWeight.Bold,modifier=Modifier.align(Alignment.BottomCenter).padding(bottom=42.dp).background(Color(0xBB000000),RoundedCornerShape(6.dp)).padding(horizontal=10.dp,vertical=4.dp))
    if(infoVisible){if(item.kind=="LIVE")Column(Modifier.fillMaxWidth().background(Brush.verticalGradient(listOf(Color(0xEE07101F),Color(0xC51A2740),Color(0x22000000)))).padding(horizontal=36.dp,vertical=20.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text(channelNumber?.toString()?:"TV",fontSize=40.sp,fontWeight=FontWeight.Light,color=Color.White,modifier=Modifier.width(76.dp));Column(Modifier.weight(1f)){Text(item.title,fontSize=21.sp,fontWeight=FontWeight.Bold,color=Color.White,maxLines=1,overflow=TextOverflow.Ellipsis);Text(epgTitle(now)?:"Programmazione non disponibile",fontSize=14.sp,fontWeight=FontWeight.SemiBold,color=Color.White,maxLines=1,overflow=TextOverflow.Ellipsis);Text(epgTime(now)?:"Orario non disponibile",fontSize=11.sp,color=Color(0xFFD7DEEA));epgDescription(now)?.let{Text(it,fontSize=10.sp,color=Color(0xFFBFC9D8),maxLines=2,overflow=TextOverflow.Ellipsis,modifier=Modifier.padding(top=3.dp))}}};epgProgress(now)?.let{value->Spacer(Modifier.height(10.dp));LinearProgressIndicator(progress={value},modifier=Modifier.fillMaxWidth().height(3.dp),color=Color.White,trackColor=Color(0x55FFFFFF))}}else Column(Modifier.fillMaxWidth().background(Brush.verticalGradient(listOf(Color(0xE6000000),Color.Transparent))).padding(horizontal=34.dp,vertical=26.dp)){Text(item.title,fontSize=23.sp,fontWeight=FontWeight.Bold,color=Color.White,maxLines=1,overflow=TextOverflow.Ellipsis)}}
  }
}

fun parseXtream(address:String):Xtream?{return try{val uri=Uri.parse(address);val user=uri.getQueryParameter("username")?:return null;val pass=uri.getQueryParameter("password")?:return null;Xtream("${uri.scheme}://${uri.encodedAuthority}",user,pass,address)}catch(_:Exception){null}}
fun subscriptionExpiry(x:Xtream):String{return try{val api="${x.server}/player_api.php?username=${Uri.encode(x.username)}&password=${Uri.encode(x.password)}";val info=JSONObject(httpText(api)).optJSONObject("user_info")?:return "Non disponibile";val raw=info.optString("exp_date");if(raw.isBlank()||raw=="null"||raw=="0")"Nessuna scadenza indicata"else java.text.SimpleDateFormat("dd/MM/yyyy",java.util.Locale.ITALY).format(java.util.Date(raw.toLong()*1000))}catch(_:Exception){"Non disponibile"}}
fun loadMediaDetails(x:Xtream,item:IptvItem):MediaDetails{val series=item.kind=="SERIE";val id=(if(series)item.seriesId else item.streamId).orEmpty();val action=if(series)"get_series_info&series_id"else"get_vod_info&vod_id";val api="${x.server}/player_api.php?username=${Uri.encode(x.username)}&password=${Uri.encode(x.password)}&action=$action=${Uri.encode(id)}";val root=JSONObject(httpText(api));val info=root.optJSONObject("info")?:root.optJSONObject("movie_data")?:root;fun value(vararg keys:String):String{for(key in keys){val found=info.optString(key);if(found.isNotBlank()&&found!="null")return found};return ""};return MediaDetails(item.title,value("plot","description","biography"),value("releaseDate","releasedate","year"),value("genre"),value("rating","rating_5based"),value("duration","duration_secs"),value("director"),value("cast","actors"))}
fun importSource(address:String):Imported{val x=parseXtream(address);if(x!=null){val base="${x.server}/player_api.php?username=${Uri.encode(x.username)}&password=${Uri.encode(x.password)}";val map=linkedMapOf<String,List<Category>>();map["LIVE"]=parseCategories(httpText("$base&action=get_live_categories"));map["FILM"]=parseCategories(httpText("$base&action=get_vod_categories"));map["SERIE"]=parseCategories(httpText("$base&action=get_series_categories"));if(map.values.all{it.isEmpty()})throw Exception("Il server non ha restituito categorie");return Imported(x,map,emptyList())};val all=parseM3u(address);return Imported(null,emptyMap(),all)}
fun parseCategories(text:String):List<Category>{val array=JSONArray(text);return List(array.length()){i->val row=array.getJSONObject(i);Category(row.optString("category_id"),row.optString("category_name","Altri"))}}
fun loadXtreamCategory(x:Xtream,section:String,category:Category):List<IptvItem>{val action=when(section){"LIVE"->"get_live_streams";"FILM"->"get_vod_streams";else->"get_series"};val base="${x.server}/player_api.php?username=${Uri.encode(x.username)}&password=${Uri.encode(x.password)}&action=$action&category_id=${Uri.encode(category.id)}";return parseXtreamItems(x,section,JSONArray(httpText(base)),mapOf(category.id to category.name))}
suspend fun loadFullCatalog(x:Xtream,categories:Map<String,List<Category>>):List<IptvItem> = coroutineScope{listOf("LIVE","FILM","SERIE").map{section->async(Dispatchers.IO){runCatching{val action=when(section){"LIVE"->"get_live_streams";"FILM"->"get_vod_streams";else->"get_series"};val base="${x.server}/player_api.php?username=${Uri.encode(x.username)}&password=${Uri.encode(x.password)}&action=$action";val names=categories[section].orEmpty().associate{it.id to it.name};parseXtreamItems(x,section,JSONArray(httpText(base)),names)}.getOrDefault(emptyList())}}.flatMap{it.await()}.distinctBy{it.id}}
fun parseXtreamItems(x:Xtream,section:String,array:JSONArray,categoryNames:Map<String,String>):List<IptvItem>{return List(array.length()){i->val row=array.getJSONObject(i);val id=if(section=="SERIE")row.optString("series_id")else row.optString("stream_id");val categoryId=row.optString("category_id");val group=categoryNames[categoryId]?:"Altri";val ext=row.optString("container_extension",if(section=="LIVE")"ts"else"mp4");val stream=when(section){"LIVE"->"${x.server}/live/${x.username}/${x.password}/$id.$ext";"FILM"->"${x.server}/movie/${x.username}/${x.password}/$id.$ext";else->""};val image=if(section=="SERIE")row.optString("cover")else row.optString("stream_icon");IptvItem("$section-$id",row.optString("name","Senza titolo"),stream,group,section,if(section=="SERIE")id else null,image,id,row.optString("epg_channel_id"))}}
fun loadEpisodes(x:Xtream,series:IptvItem):List<IptvItem>{val api="${x.server}/player_api.php?username=${Uri.encode(x.username)}&password=${Uri.encode(x.password)}&action=get_series_info&series_id=${Uri.encode(series.seriesId)}";val episodes=JSONObject(httpText(api)).optJSONObject("episodes")?:throw Exception("Nessun episodio disponibile");val result=mutableListOf<IptvItem>();for(season in episodes.keys()){val rows=episodes.optJSONArray(season)?:continue;for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val id=row.optString("id");val ext=row.optString("container_extension","mp4");result+=IptvItem("EP-$id",row.optString("title","Episodio ${i+1}"),"${x.server}/series/${x.username}/${x.password}/$id.$ext","Stagione $season","EPISODIO",image=series.image)}};if(result.isEmpty())throw Exception("Nessun episodio disponibile");return result}

fun isAdult(value:String):Boolean{val text=value.lowercase();return listOf("xxx","adult","18+","erotic","porn").any{text.contains(it)}}
fun prepareHome(x:Xtream,categories:Map<String,List<Category>>):Pair<List<IptvItem>,List<IptvItem>>{val liveCats=categories["LIVE"].orEmpty();val preferred=listOf("italia","sky","dazn");val chosenLive=(preferred.mapNotNull{word->liveCats.firstOrNull{it.name.contains(word,true)}}+liveCats.take(1)).distinctBy{it.id}.take(4);val live=chosenLive.flatMap{runCatching{loadXtreamCategory(x,"LIVE",it).take(10)}.getOrDefault(emptyList())}.distinctBy{it.id};val movieCats=categories["FILM"].orEmpty().filterNot{isAdult(it.name)}.shuffled().take(4);val movies=movieCats.flatMap{runCatching{loadXtreamCategory(x,"FILM",it).shuffled().take(12)}.getOrDefault(emptyList())}.filterNot{isAdult(it.group)||isAdult(it.title)}.distinctBy{it.id}.shuffled();return live to movies}
fun loadCurrentPrograms(x:Xtream,channels:List<IptvItem>):Map<String,String>{val result=linkedMapOf<String,String>();for(channel in channels.take(80)){try{val base="${x.server}/player_api.php?username=${Uri.encode(x.username)}&password=${Uri.encode(x.password)}&stream_id=${Uri.encode(channel.streamId)}";var root=JSONObject(httpText("$base&action=get_short_epg&limit=8"));var rows=root.optJSONArray("epg_listings")?:root.optJSONArray("listings");if(rows==null||rows.length()==0){root=JSONObject(httpText("$base&action=get_simple_data_table"));rows=root.optJSONArray("epg_listings")?:root.optJSONArray("listings")};if(rows==null)continue;val now=System.currentTimeMillis()/1000;var fallback="";for(i in 0 until rows.length()){val row=rows.getJSONObject(i);val title=decodeEpg(row.optString("title"));val start=row.optLong("start_timestamp",row.optString("start_timestamp").toLongOrNull()?:0);val stop=row.optLong("stop_timestamp",row.optString("stop_timestamp").toLongOrNull()?:row.optLong("end_timestamp"));if(fallback.isBlank()&&title.isNotBlank())fallback=packEpg(title,start*1000,stop*1000);if(start>0&&stop>0&&start<=now&&stop>=now){result[channel.id]=packEpg(title,start*1000,stop*1000);break}};if(result[channel.id].isNullOrBlank()&&fallback.isNotBlank())result[channel.id]=fallback}catch(_:Exception){}};return result}
fun decodeEpg(value:String):String{if(value.isBlank())return "";return try{String(Base64.decode(value,Base64.DEFAULT),Charsets.UTF_8)}catch(_:Exception){value}}
fun readFavorites(text:String):List<IptvItem>{return try{val rows=JSONArray(text);List(rows.length()){i->val row=rows.getJSONObject(i);IptvItem(row.optString("id"),row.optString("title"),row.optString("url"),row.optString("group"),row.optString("kind"),row.optString("seriesId").ifBlank{null},row.optString("image"),row.optString("streamId"))}}catch(_:Exception){emptyList()}}
fun writeFavorites(items:List<IptvItem>):String{val rows=JSONArray();items.forEach{item->rows.put(JSONObject().put("id",item.id).put("title",item.title).put("url",item.url).put("group",item.group).put("kind",item.kind).put("seriesId",item.seriesId?:"").put("image",item.image).put("streamId",item.streamId))};return rows.toString()}
fun readProfiles(text:String):List<PlaylistProfile>{return try{val rows=JSONArray(text);List(rows.length()){i->val row=rows.getJSONObject(i);PlaylistProfile(row.optString("name","Playlist"),row.optString("url"),row.optInt("avatar",i%12))}.filter{it.url.isNotBlank()}}catch(_:Exception){emptyList()}}
fun writeProfiles(items:List<PlaylistProfile>):String{val rows=JSONArray();items.forEach{rows.put(JSONObject().put("name",it.name).put("url",it.url).put("avatar",it.avatar))};return rows.toString()}
fun readStringList(text:String):List<String>{return try{val rows=JSONArray(text);List(rows.length()){rows.optString(it)}}catch(_:Exception){emptyList()}}
fun writeStringList(items:List<String>):String{val rows=JSONArray();items.forEach{rows.put(it)};return rows.toString()}
fun httpText(address:String):String{val c=URL(address).openConnection() as HttpURLConnection;c.instanceFollowRedirects=true;c.connectTimeout=20_000;c.readTimeout=90_000;c.setRequestProperty("User-Agent","LMIPTV-FireTV/1.1");c.setRequestProperty("Accept-Encoding","gzip");if(c.responseCode !in 200..299)throw Exception("Errore server HTTP ${c.responseCode}");val input=if(c.contentEncoding?.contains("gzip",true)==true)GZIPInputStream(c.inputStream)else c.inputStream;return input.bufferedReader().use{it.readText()}}
fun parseM3u(address:String):List<IptvItem>{val c=URL(address).openConnection() as HttpURLConnection;c.instanceFollowRedirects=true;c.connectTimeout=20_000;c.readTimeout=120_000;c.setRequestProperty("User-Agent","LMIPTV-FireTV/1.1");if(c.responseCode !in 200..299)throw Exception("Errore server HTTP ${c.responseCode}");val input=if(c.contentEncoding?.contains("gzip",true)==true)GZIPInputStream(c.inputStream)else c.inputStream;val reader=BufferedReader(InputStreamReader(input));val result=mutableListOf<IptvItem>();var title="";var group="Altri";val regex=Regex("group-title=\\\"([^\\\"]*)\\\"",RegexOption.IGNORE_CASE);reader.useLines{lines->lines.forEach{raw->val line=raw.trim();if(line.startsWith("#EXTINF",true)){title=line.substringAfterLast(',').trim().ifBlank{"Senza nome"};group=regex.find(line)?.groupValues?.get(1)?.ifBlank{"Altri"}?:"Altri"}else if(line.isNotBlank()&&!line.startsWith("#")){val low=line.lowercase();val gl=group.lowercase();val kind=when{low.contains("/series/")||gl.contains("serie")->"SERIE";low.contains("/movie/")||gl.contains("film")||gl.contains("vod")||gl.contains("cinema")->"FILM";else->"LIVE"};result+=IptvItem("M3U-${result.size}",title.ifBlank{line.substringAfterLast('/')},line,group,kind)}}};if(result.isEmpty())throw Exception("Playlist vuota o non riconosciuta");return result}
























